export const LIB_REFERENCE: Record<string, LibReference> = {
  "auth": {"global":"AIMEAT.auth","script":"/v1/libs/aimeat-auth.js","what":"Sign-in and the session: the login button, the signed-in person, an authenticated fetch.","members":[{"name":"register","call":"register(username, displayName, opts = {})","doc":"Register a new human identity (GHII) and get an authenticated session.\n\nThe account signs in with a password, always: the session comes from POST /v1/ghii/login and\nrenews with the httpOnly refresh cookie. A call without `opts.password` used to sign in with the\naccount key (POST /v1/auth/token), which node 4.0.0 removes (OWNER_KEY_LOGIN_REMOVED_IN). Such a\ncall now gets a strong random password, made here and sent only to this node; the returned\nsession carries it once as `generatedPassword` (never stored), so the caller can show it to the\nperson, who needs it to sign in again on another device or after the session ends.\n@param {string} username\n@param {string} displayName\n@param {{ password?: string, bio?: string, avatar?: string, locale?: string }} [opts]\n@returns {Promise<object>} Session object with .fetch(), .refresh(), .jwt, .ghii (and\n  .generatedPassword when the caller gave no password)"},{"name":"login","call":"login(username)","doc":"Login with stored credentials (auto-refreshes JWT if expired).\n@returns {Promise<object|null>} Session or null if no stored credentials"},{"name":"signIn","call":"signIn(opts)","doc":"Sign in, interactively. Call it from a click handler: on an app origin it may open the consent\npopup, and a browser opens a popup only inside a user gesture.\n\nOn an app origin this is the silent bridge with the visible consent step allowed; anywhere else\nit opens the sign-in modal, with `opts` passed to it ({ tab: 'register', onLogin, i18n }).\nResolves to the session, or null when nobody signed in: the popup was closed or blocked, the\nmodal was dismissed, or the app asks for a scope this node cannot grant. An existing session is\nreturned as it is, and reports nothing.\n\n`opts.onLogin(session)` and `opts.onSession(session, { restored })` are called once, in both\ncases, for the session this call produced (on-login.js). onLogin was the modal's to call until\n2026-09-13, so on an app origin nobody called it.\n\nAdded 2026-09-13. Before it the login pill's own button was the only interactive sign-in, and\napps reached it by clicking `#login button`, which is the theme control that renders first.\n@param {object & { onLogin?: Function, register?: boolean, tab?: string }} [opts]\n@returns {Promise<object|null>}"},{"name":"loginWithPassword","call":"loginWithPassword(username, password, secondFactor)","doc":"Login with username + password (works from any device).\n\nAn account with two-step sign-in refuses the first call with code TOTP_REQUIRED; call again with\nthe second factor. The password travels a second time on purpose: the server holds no partial\nlogin state between the two calls, so there is nothing a stolen intermediate token could carry.\n\n@param {string} username\n@param {string} password\n@param {{ totpCode?: string, backupCode?: string }} [secondFactor] The code from the\n  authenticator app, or one unused backup code. Pass one, not both.\n@returns {Promise<object>} Session object"},{"name":"signInWithPasskey","call":"signInWithPasskey(username)","doc":"Sign in with a passkey. `username` is optional and leaving it out is the better path: the\nceremony is discoverable, the device offers whatever it holds for this domain, and its answer\nnames the account. Ends in the same session the password path builds, because the server ends\nin the same response.\n\nThrows with code PASSKEY_CANCELLED when the person closed the prompt, which a caller should\ntreat as \"they changed their mind\" rather than as a failure to show in red."},{"name":"adoptLoginAnswer","call":"adoptLoginAnswer(data)","doc":"The answer of POST /v1/ghii/login/two-step/finish is a sign-in answer: the session it carries."},{"name":"addPasskey","call":"addPasskey(label)","doc":"Add THIS device to the signed-in account. Returns the stored passkey as the node describes it."},{"name":"getSession","call":"getSession()","doc":"The signed-in person's session, or null when nobody is signed in: the object onSession receives.\n@returns {AuthSession|null}"},{"name":"offlineIdentity","call":"offlineIdentity()","doc":"Who to open an offline copy for: { owner, ghii, displayName, at } when this page load restored no\nsession because the node gave no answer and somebody signed in on this browser before; null while\na session is live and whenever the node was reached. It names a person and authorises nothing.\nThe 'offline' event carries the same value when it is found (last-identity.js)."},{"name":"updateSessionMeta","call":"updateSessionMeta(patch)","doc":"Patch mutable, non-secret session metadata in place (e.g. displayName after a profile edit),\npersist it, and notify the login pill so it re-renders live — no page reload."},{"name":"logout","call":"logout()","doc":"Logout — clear stored credentials from localStorage and IndexedDB.\nORDER MATTERS: local state is dropped and 'logout' emitted SYNCHRONOUSLY, before the revoke.\n\"Logged out\" must not depend on a network round-trip — with the revoke awaited first, every\nsubscriber reading getSession() meanwhile still saw the old session, which is how the header\nkept the bell and \"Me\" next to a \"Sign In\" button (2026-08-07). Revoke + apex logout are\nbest-effort cleanup that runs after the UI already shows the truth."},{"name":"manageGrant","call":"manageGrant()","doc":"Re-open the consent screen for the current app (H-2 in-app grant management)."},{"name":"isAppOrigin","call":"isAppOrigin()","doc":"True inside a published app that is kept apart from the node: on its own origin, or in the node's isolated frame."},{"name":"showLoginModal","call":"showLoginModal(opts)","doc":"Open the sign-in modal (password + Google if configured). If a session arrives while it is open,\n `opts.onLogin(session)` and `opts.onSession(session, { restored })` are called once (on-login.js).\n `opts.redirect` is where an emailed sign-in link returns the person; this page when absent."},{"name":"on","call":"on(event, fn)","doc":"Register an event listener. A 'login' listener gets (session, { restored })."},{"name":"off","call":"off(event, fn)","doc":"Remove an event listener"},{"name":"requestParentAuth","call":"requestParentAuth(timeout = 3000)","doc":"Request auth credentials from the parent window via postMessage (sandboxed-iframe fallback).\n@returns {Promise<object|null>} Session-like object with .jwt and .fetch(), or null"},{"name":"mountLoginButton","call":"mountLoginButton(selector, opts = {})","doc":"Mount the login button, which handles the whole sign-in and shows the signed-in person's name,\nthe language switch, the theme switch and sign-out. Delegates the render to pill.js.\nSHOW THE APP FROM onSession: it runs once for every session that becomes available, the\nrestore on page load (`restored: true`) and a sign-in (`restored: false`), so it is the one\nhandler a page needs. onLogin runs after a sign-in or a registration only, never for a restored\nsession (on-login.js). Never reload the page from either.\n@param {string|Element|object} selector - CSS selector, DOM element, OR (options-first) the opts.\n@param {MountLoginOptions} [opts]"},{"name":"getLang","call":"getLang(locales)","doc":"Locale, resolved the ONE way this platform resolves it ('aimeat-lang': ?lang= -> localStorage\n-> cookie -> navigator). The pill renders the control; these let an app read and set the same\nvalue without re-implementing the lookup and drifting from it. They hang off `auth` (NOT the\nreturn of attach(), which is the whole window.AIMEAT namespace) so they land on AIMEAT.auth."},{"name":"setLang","call":"setLang(lang)","doc":"Set the language for this browser, as the login button's own switch does: it is remembered and\n'aimeat-lang-change' fires on window, which is the event to draw the screen again from."},{"name":"getPalette","call":"getPalette()","doc":"Palette (the designed look, orthogonal to light/dark — 'aimeat-palette' + <html data-palette>).\nThe pill renders the picker; these let an app read/set/enumerate the same value."},{"name":"setPalette","call":"setPalette(id)","doc":"Set the palette by its id, one of getPalettes()."},{"name":"getPalettes","call":"getPalettes()","doc":"Every palette this node has, as { id, label, swatch }."}],"types":["@typedef {object} AuthSession\n@property {string} owner  the account name, for example \"alice\"\n@property {string|null} ghii  the person's full identity, \"alice@node-id\"\n@property {string|null} gaii  an agent's identity when the session is an agent's, else null\n@property {string|null} identity  gaii when there is one, else ghii\n@property {string} displayName  the name the person chose to show; may be empty, so show `owner` then\n@property {string[]} roles\n@property {string} nodeUrl  the node's address\n@property {boolean} federated  true for a visitor signed in from another node\n@property {string} homeNode  that visitor's own node id, else empty\n@property {string} homeUrl  that node's address, else empty\n@property {(path: string, opts?: RequestInit) => Promise<{ ok: boolean, data?: any, error?: { code: string, message: string } }>} fetch\n  an authenticated call to the node; answers the parsed envelope for every status and does not\n  throw on a refusal, so branch on `ok`\n@property {() => Promise<any>} refresh  renews the session; the library does it by itself before expiry\n@property {(title: string, opts?: { body?: string, link?: string, type?: string }) => Promise<any>} notify\n  sends the person a notification","@typedef {object} MountLoginOptions\n@property {(session: AuthSession, how: { restored: boolean }) => void} [onSession]\n  once for every session that becomes available, a restore and a sign-in alike: show the app here\n@property {(session: AuthSession) => void} [onLogin]  after a sign-in or a registration only\n@property {() => void} [onLogout]\n@property {string[]} [locales]  the languages the app has (or `<meta name=\"aimeat-locales\"\n  content=\"en fi\">`): with two or more the button shows a language switch, with fewer none\n@property {boolean} [compact]  default true: one small button with the rest in a popover at\n  600 px and under; false keeps the full row at every width\n@property {string} [buttonText]  replaces the words on the signed-out button\n@property {string} [nameHref]  makes the person's name a link\n@property {Record<string, string>} [i18n]  replaces the button's own labels"]},
  "data": {"global":"AIMEAT.data","script":"/v1/libs/aimeat-data.js","what":"The signed-in person's own records on the node: read, write with a version, list, search, and an extension's action.","members":[{"name":"set","call":"set(key, value, opts)","doc":"Write or upsert a memory entry. `{ expectedVersion: n }` is the node's optimistic lock: the\nwrite is refused (VERSION_CONFLICT) when the record is no longer at version n, so a page that\nsaves its whole copy cannot write over a change an AI or another tab made meanwhile.\n@param {string} key\n@param {any} value\n@param {Record<string, any> & { expectedVersion?: number }} [opts]"},{"name":"get","call":"get(key, opts)","doc":"Read a single entry's value. Resolves null ONLY when the key does not exist; a read the node\nrefused (401, 403, 429, 5xx) throws an Error whose `code` is the node's (RATE_LIMITED,\nACCESS_DENIED, INTERNAL_ERROR, …). That is what makes \"read, change, write the whole value\" safe:\nthe write after a refused read never runs, so it cannot replace the stored record with a default.\nUses ?soft=1 so a missing key is a clean 200 (value null), with no 404 in the browser console.\n\nWhen the caller's own key is missing or empty, the app creator's public value of the same key is\nread instead (the seed an app ships with). That fallback runs only after \"does not exist\", never\nafter a refusal, and only on an unscoped read. If the creator read itself fails it is logged and\nget() resolves null, because the caller's own key is still absent.\n\n@param {string} key\n@param {{ agent?: string, ownerScope?: boolean }} [opts] read from one of the owner's agents'\n  namespaces, or across the owner's whole set (GHII + agents)."},{"name":"getEntry","call":"getEntry(key, opts)","doc":"Read full entry metadata. opts: { agent, ownerScope } as in get().\n`provenance` is folded in from the envelope's `meta` — see withProvenance()."},{"name":"update","call":"update(key, value, version, opts)","doc":"Update with optimistic locking"},{"name":"patch","call":"patch(key, patch, opts)","doc":"Change some fields of a record and keep the rest (PATCH /v1/memory/:key, a JSON Merge Patch:\na field set to null is removed, an array is replaced whole). The node merges into the stored\nvalue, so a field an AI wrote meanwhile stays. `{ ifVersion: n }` refuses the merge when the\nrecord is no longer at version n; `{ ownerScope: true }` patches the owner's copy.\n@param {string} key\n@param {Record<string, any>} patch\n@param {{ ifVersion?: number, ownerScope?: boolean, visibility?: string, tags?: string[] }} [opts]\n@returns {Promise<any>}"},{"name":"delete","call":"delete(key, opts)","doc":"Delete an entry.\n\n`{ ownerScope: true }` deletes the key wherever it sits in this owner's scope — including a\nnamespace one of their agents wrote it into. `list({ ownerScope: true })` already returns those\nkeys, so without the same opt-in here an app can show a record it cannot remove.\n\n@param {string} key\n@param {{ ownerScope?: boolean }} [opts]"},{"name":"list","call":"list(opts)","doc":"List memory keys.\n\nopts:\n  prefix, visibility, tags   — as before\n  agent      — list ONE of the owner's agents' namespaces (full GAII `name#owner@node`)\n  ownerScope — list across the owner's GHII + every same-owner agent. An owner session\n               already gets this server-side; an app-grant token needs it stated.\n  meta       — omit every `value` and report each entry's `bytes` instead. Use this for\n               any listing you render as a table/board: the default response inlines\n               every value, so a fleet-wide prefix can be megabytes per call.\n  count      — return only `{ count }` (server-side COUNT, no values). A cheap\n               \"did anything change?\" probe; its cache is dropped by any memory write."},{"name":"count","call":"count(opts)","doc":"Cheap change probe: the number of keys under a prefix, no values transferred."},{"name":"discover","call":"discover(prefix, opts)","doc":"List OTHER people's public entries under a key prefix, with their values. The read for a shared\nfeed, a public leaderboard or a community map: each user writes their own public key, and this is\nhow everyone else finds them.\n\nsearch() and list() never do this. They read the caller's own identity set (the signed-in person\nand their agents), so a feed built on them shows each visitor only their own posts, which looks\nlike \"nobody has posted yet\" and is invisible on a one-account test. This calls\nGET /v1/memory/discover, which lists public entries across the node's users but carries no values\nand leaves the caller out, and makes up both: one public read per row (at most six at a time) and\nthe caller's own public entries under the prefix, marked `mine: true`.\n\nIt needs a signed-in session, because the listing route does: a signed-out visitor gets the usual\n\"Not logged in\" error, so design that state rather than rendering it as an empty feed. A row whose\nvalue is gone by the time it is read (deleted, or made private) is left out; if every read fails,\nthe first error is thrown instead of returning an empty list.\n\n@param {string} prefix  Key prefix, e.g. 'myapp.feed.'.\n@param {{ limit?: number, offset?: number, owner?: string, withValues?: boolean, includeMine?: boolean }} [opts]\n  limit       rows asked of the node, 1 to 200 (default 50); it pages with offset.\n  owner       only entries whose owner GAII starts with this.\n  withValues  false returns metadata only and makes no public reads (default true).\n  includeMine false leaves the caller's own entries out, as the route does (default true).\n@returns {Promise<Array<{ key: string, owner_gaii: string, value?: any, visibility: string,\n  tags?: string[], version?: number, created_at?: string, updated_at?: string, mine: boolean }>>}\n  The caller's own rows first, then everyone else's in the node's order."},{"name":"search","call":"search(query, opts)","doc":"Search memory entries\nopts: { visibility, agent, ownerScope } — scoping as in list().\nReads the CALLER's own identity set only; other people's public entries come from discover()."},{"name":"getPublic","call":"getPublic(gaii, key)","doc":"Read another agent's public memory (no auth needed). ?soft=1: missing (or hidden)\nkeys resolve null via a clean 200 instead of logging a console 404.\n\nReturns the VALUE, deliberately unchanged: every published app reading this library expects\nthe bare value here, so widening the return type would break them all. To see how the value\nwas made, use getPublicEntry() below."},{"name":"getPublicEntry","call":"getPublicEntry(gaii, key)","doc":"The same public read, as a full entry: `{ key, value, visibility, version, …, provenance }`.\n\nWHY THIS EXISTS. The node serves an item's AI provenance on the envelope's `meta`, and\ngetPublic() returns `res.data.value` — so the statement about how the content was made was\nbeing thrown away at the last hop, on the one read path published apps actually use. An app\ncould render a model-written article and have no way to say so, however carefully the writing\nagent had declared it. This is the same READ-DIRECTION loss that had to be fixed in the\nconnector (ai-provenance-carry.ts v1.1.0, \"read_provenance() never returns anything\"); the\nbrowser library had it too.\n\n`provenance` is `{ id, record, record_url }` or undefined when the node holds no record for\nthe item. Undefined means UNSTATED, and never \"a person wrote it\"."},{"name":"appConfig","call":"appConfig()","doc":"This app's config: the values its owner set for the fields the app declares in its\n`<script type=\"application/json\" id=\"aimeat-config\">` block, with the declared defaults filled\nin. The OWNER's values, whoever opened the app, signed in or not, which is why a config field\nis never a secret. Resolves null on a page that is not a served app, or when the node says the\napp is not found. A read that fails in any other way (a refusal, the network, an answer that is\nnot JSON) throws, with the node's `code` when it sent one: a config the app could not read is\nnot a config the app does not have.\n@returns {Promise<Record<string, string|number|boolean>|null>}"},{"name":"appWorkspace","call":"appWorkspace(contract)","doc":"Where this installed copy's workspace for a contract the app declares in its\n`<script type=\"application/json\" id=\"aimeat-workspace\">` block is: `{ organism_id, workspace_id,\nname }`, made when a set was installed. Resolves null when no install made one (the app was not\ninstalled from a set, or the page is not a served app); the app then finds or creates its own.\nA read that fails throws, as appConfig() does, so a refused read never leads the app to create a\nsecond workspace beside the one the install made.\n@param {string} contract e.g. \"aimeat.backoffice/1\"\n@returns {Promise<{ organism_id: string, workspace_id: string, name?: string }|null>}"},{"name":"adultStatus","call":"adultStatus()","doc":"Whether the signed-in person is a verified adult: { verified, method, verified_at }, never a birth\ndate. `method` is 'ftn' (bank identification), 'eudiw' (EUDI wallet) or 'credit-card' (a payment\nwith a credit card). Nobody signed in reads as not verified. Show adult content only when\n`verified` is true, and gate it in the extension too (ctx.caller.adult), not only in the page.\n@returns {Promise<{ verified: boolean, method: string|null, verified_at: string|null }>}"},{"name":"action","call":"action(ext, actionId, input)","doc":"Run an action of an extension and answer what it returns. Sent with the signed-in person's\nsession when there is one, and without any credential otherwise, so a public action also works\nfor a visitor. A refusal throws, with the extension's own code and message.\n@param {string} ext  `name`, `name/instanceId`, `owner/name` or `owner/name/instanceId`\n@param {string} actionId\n@param {Record<string, any>} [input]\n@returns {Promise<any>} the action's `data`"}],"types":[]},
  "i18n": {"global":"AIMEAT.i18n","script":"/v1/cortex/aimeat-i18n/libs/aimeat-i18n.js","what":"The words: translations, the language in use and its switch.","members":[{"name":"init","call":"init(opts)","doc":"init({ keyBase?, locales, default?, fallback?, translations? })\n - translations: optional inline map { en:{...}, fi:{...} } (used as-is, no memory read)\n - keyBase: memory key prefix; locale dicts read from `${keyBase}.${locale}` via AIMEAT.data"},{"name":"t","call":"t(key, vars)","doc":"The text for `key` in the language in use: the flat key first (`\"list.empty\"` as one key), then\nthe same words as a path (`list` then `empty`), then the fallback language, then the key itself.\n`{name}` in the text is replaced from `vars`.\n@param {string} key\n@param {Record<string, string|number>} [vars]\n@returns {string}"},{"name":"setLocale","call":"setLocale(locale)","doc":"Change the language. Loads its texts, remembers the choice in this browser (the `aimeat-lang`\nkey and cookie the sign-in library reads too) and fires `aimeat-lang-change` and\n`aimeat-i18n-changed` on window: draw the screen again from one of them, because t() answers the\nnew language only from then on. A language that is not in init()'s `locales` changes nothing.\n@param {string} locale\n@returns {Promise<string>} the language in use after the call"},{"name":"getLocale","call":"getLocale()","doc":"The language in use, for example \"fi\". @returns {string}"},{"name":"locales","call":"locales()","doc":"The languages init() was given, in its order. @returns {string[]}"},{"name":"available","call":"available()","doc":"Has init() been given at least one language? @returns {boolean}"},{"name":"LanguageSwitcher","call":"LanguageSwitcher(opts)","doc":"A select of the languages init() was given, which calls setLocale() on a change. An app that\nmounts the login button with its languages (AIMEAT.auth.mountLoginButton, `locales`) already\nhas a language switch in the bar and needs no second one.\n@param {{ target?: string|Element, labels?: Record<string, string>, className?: string,\n  onChange?: (locale: string) => void }} [opts]\n@returns {{ el: HTMLSelectElement, destroy: () => void }}"},{"name":"apply","call":"apply(root)","doc":"Translate every [data-i18n] element in root (textContent). Optional [data-i18n-attr]."}],"types":[]},
  "fmt": {"global":"AIMEAT.fmt","script":"/v1/cortex/aimeat-i18n/libs/aimeat-i18n.js","what":"How things are written: dates, times, numbers, money and durations in the person's own format and clock.","members":[{"name":"use","call":"use(prefs)","doc":"Tell the library how this reader writes things: fmt.use({ region, timezone }).\n\nAn app that has the person's profile passes it here once. An app that does not, does not call\nit, and every formatter follows the browser."},{"name":"useProfile","call":"useProfile()","doc":"Read the settings off the signed-in person's profile, when the app is running on their node.\nResolves to the settings either way; a signed-out reader simply follows their browser.\n\nWITH THE APP'S OWN SESSION. An app signs in through aimeat-auth, which holds a bearer token, not\na cookie: the plain same-origin fetch this used before carried no credential and answered 401\non every app origin, so the settings never arrived. With aimeat-auth loaded the read goes\nthrough session.fetch, the same read aimeat-auth's own AIMEAT.auth.displayPrefs() makes.\nSigned out, or a visitor from another node (their profile lives on their home node): no read,\nand the browser. A page without aimeat-auth keeps the plain fetch it always had."},{"name":"region","call":"region()","doc":""},{"name":"timezone","call":"timezone()","doc":""},{"name":"num","call":"num(n, opts)","doc":"A number in the person's regional format. `opts` are Intl.NumberFormat's. Not a finite number: \"—\".\n@param {number} n @param {Intl.NumberFormatOptions} [opts] @returns {string}"},{"name":"number","call":"number(n, opts)","doc":"A number in the person's regional format. `opts` are Intl.NumberFormat's. Not a finite number: \"—\".\n@param {number} n @param {Intl.NumberFormatOptions} [opts] @returns {string}"},{"name":"date","call":"date(v, opts)","doc":"A calendar date in the person's regional format and time zone. `v` is a Date, a timestamp or a\ndate string; `opts` are Intl.DateTimeFormat's, and a `timeZone` named there is kept. No date: \"—\".\n@param {Date|number|string} v @param {Intl.DateTimeFormatOptions} [opts] @returns {string}"},{"name":"time","call":"time(v, opts)","doc":"A time of day in the person's regional format and time zone; `v` and `opts` as in date().\n@param {Date|number|string} v @param {Intl.DateTimeFormatOptions} [opts] @returns {string}"},{"name":"dateTime","call":"dateTime(v, opts)","doc":"A date and a time together in the person's regional format and time zone; `v` and `opts` as in date().\n@param {Date|number|string} v @param {Intl.DateTimeFormatOptions} [opts] @returns {string}"},{"name":"duration","call":"duration(ms, opts)","doc":"A LENGTH OF TIME — \"1pv 23t 26min\" — in the reader's own language and their own shorthand.\n\nA different question from relative(), which says how long AGO. This is a span: an uptime, a\ncountdown, how long a job took.\n\nDO NOT REACH FOR A TRANSLATION KEY HERE. `{n} pv` survives Finnish only because `pv` does not\ninflect; one `{n}` cannot carry a language whose noun changes with the number (Polish `1 dzień`\nbut `2 dni`, Russian `1 день`, `2 дня`, `5 дней`), and no key can produce \"eilen\". CLDR holds\nevery one of those rules and Intl reads them.\n\n@param {number} ms how long, in milliseconds; a negative span is read as its length\n@param {Object} [opts] `max` is how many units may appear (default 3). Everything else goes to\n  Intl.DurationFormat, so `{ style: 'long' }` spells the units out."},{"name":"relative","call":"relative(v)","doc":"\"3 days ago\", \"in 2 hours\"."},{"name":"money","call":"money(n, currency, opts)","doc":"AN AMOUNT OF MONEY. Refuses morsels, on purpose and loudly.\n\nA morsel is a PACER, not a currency and not a credit: it paces what agents may push into the\nstore, it accrues while the owner is idle, and it buys nothing. Money is a separate matter with\nits own rails, and it sits beside morsels rather than counting them. The two are numbers of\nsimilar size on the same screens, so a formatter that accepted both would put a euro sign over\nsomebody's pacing meter — which would tell every reader something false about what this\nplatform is. Use fmt.morsels()."},{"name":"morsels","call":"morsels(n, word)","doc":"A morsel COUNT. Never a currency symbol; the word travels with the number."},{"name":"resolvedTimeZone","call":"resolvedTimeZone()","doc":"The zone actually in force, always a real IANA name."},{"name":"zoneLabel","call":"zoneLabel(v)","doc":"How to name the zone beside a time (\"EET\"), or null when there is nothing worth saying.\n\nNull while the reader follows their browser: naming the clock somebody is already reading\nteaches them nothing. Once a zone IS chosen the label is shown every time rather than only when\nit differs from the device — a mark that appears only on a mismatch is itself the surprise."}],"types":[]},
};
